import Foundation

/**
 * A class used to format both non-`Date` times generated by the Zmanim package as well as `Date`s. For example the
 * `AstronomicalCalendar.getTemporalHour()` returns the length of the hour as a `TimeInterval`, and this class can
 * format it as a time, xsd:duration or other text. It also serializes a calendar's zmanim to XML or JSON.
 *
 * @author &copy; Eliyahu Hershfeld 2004 - 2026
 */
public class ZmanimFormatter {

    /** Setting to prepend a zero to single digit hours. */
    public var prependZeroHours = false

    /** Whether seconds are included in the formatted duration. */
    public var useSeconds = false

    /** Whether milliseconds are included in the formatted duration. */
    public var useMillis = false

    /** The `DateFormatter` pattern used by `formatDate(date:)`, such as "h:mm:ss" (the default). */
    public var dateTimeFormat = "h:mm:ss"

    /** The time zone used to format dates. */
    public var timeZone: TimeZone

    /** The time format; one of the format constants such as `SEXAGESIMAL_SECONDS_FORMAT`. */
    public var timeFormat = ZmanimFormatter.SEXAGESIMAL_SECONDS_FORMAT

    /** Format using hours, minutes, seconds and milliseconds using the xsd:time format. This format will return 00.00.00.0. */
    public static let SEXAGESIMAL_XSD_FORMAT = 0

    /** Format using hours and minutes. */
    public static let SEXAGESIMAL_FORMAT = 1

    /** Format using hours, minutes and seconds. */
    public static let SEXAGESIMAL_SECONDS_FORMAT = 2

    /** Format using hours, minutes, seconds and milliseconds. */
    public static let SEXAGESIMAL_MILLIS_FORMAT = 3

    /** Format using the <a href="https://www.w3.org/TR/xmlschema-2/#duration">XSD Duration</a> format (PT1H6M7.869S). */
    public static let XSD_DURATION_FORMAT = 4

    /**
     * Constructor that defaults to the `SEXAGESIMAL_SECONDS_FORMAT` and an "h:mm:ss" date format.
     *
     * - Parameter timeZone: the time zone used to format dates.
     */
    public convenience init(timeZone: TimeZone) {
        self.init(timeFormat: ZmanimFormatter.SEXAGESIMAL_SECONDS_FORMAT, dateTimeFormat: "h:mm:ss", timeZone: timeZone)
    }

    /**
     * ZmanimFormatter constructor.
     *
     * - Parameters:
     *   - timeFormat: one of the format constants, such as `SEXAGESIMAL_SECONDS_FORMAT`. An invalid format is ignored and
     *     the default `SEXAGESIMAL_SECONDS_FORMAT` is used and a ``KosherSwiftWarnings`` warning is reported (KosherJava throws an IllegalArgumentException).
     *   - dateTimeFormat: the `DateFormatter` pattern used to format dates, such as "h:mm:ss a".
     *   - timeZone: the time zone used to format dates.
     */
    public init(timeFormat: Int, dateTimeFormat: String, timeZone: TimeZone) {
        self.timeZone = timeZone
        self.dateTimeFormat = dateTimeFormat
        setTimeFormat(format: ZmanimFormatter.SEXAGESIMAL_SECONDS_FORMAT)
        setTimeFormat(format: timeFormat)
    }

    /** Returns the time zone used to format dates. */
    public func getTimeZone() -> TimeZone {
        return timeZone
    }

    /** Sets the time zone used to format dates. */
    public func setTimeZone(timeZone: TimeZone) {
        self.timeZone = timeZone
    }

    /** Returns the time format, one of the format constants. */
    public func getTimeFormat() -> Int {
        return timeFormat
    }

    /**
     * Sets the format to use for formatting durations.
     *
     * - Parameter format: one of `SEXAGESIMAL_XSD_FORMAT`, `SEXAGESIMAL_FORMAT`, `SEXAGESIMAL_SECONDS_FORMAT`,
     *   `SEXAGESIMAL_MILLIS_FORMAT` or `XSD_DURATION_FORMAT`. Any other value is ignored and leaves the format unchanged
     *   and reported to ``KosherSwiftWarnings`` (KosherJava throws an IllegalArgumentException).
     */
    public func setTimeFormat(format: Int) {
        switch format {
        case ZmanimFormatter.SEXAGESIMAL_XSD_FORMAT:
            setSettings(prependZeroHours: true, useSeconds: true, useMillis: true)
        case ZmanimFormatter.SEXAGESIMAL_FORMAT:
            setSettings(prependZeroHours: false, useSeconds: false, useMillis: false)
        case ZmanimFormatter.SEXAGESIMAL_SECONDS_FORMAT:
            setSettings(prependZeroHours: false, useSeconds: true, useMillis: false)
        case ZmanimFormatter.SEXAGESIMAL_MILLIS_FORMAT:
            setSettings(prependZeroHours: false, useSeconds: true, useMillis: true)
        case ZmanimFormatter.XSD_DURATION_FORMAT:
            break // the settings are N/A for this
        default:
            KosherSwiftWarnings.report("\(format) isn't a time format; use one of the format constants such as SEXAGESIMAL_SECONDS_FORMAT. The format wasn't changed (\(timeFormat))")
            return
        }
        self.timeFormat = format
    }

    /** Sets the `DateFormatter` pattern, such as "h:mm:ss a", used by `formatDate(date:)`. */
    public func setDateTimeFormat(dateTimeFormat: String) {
        self.dateTimeFormat = dateTimeFormat
    }

    /** Returns the `DateFormatter` pattern used by `formatDate(date:)`. */
    public func getDateTimeFormat() -> String {
        return dateTimeFormat
    }

    private func setSettings(prependZeroHours: Bool, useSeconds: Bool, useMillis: Bool) {
        self.prependZeroHours = prependZeroHours
        self.useSeconds = useSeconds
        self.useMillis = useMillis
    }

    /**
     * Formats a duration (such as a sha'ah zmanis) using the current time format, for example "1:06:07" with the
     * `SEXAGESIMAL_SECONDS_FORMAT`. A nil, NaN or infinite duration is formatted as 0. A negative duration starts with "-".
     *
     * - Parameter duration: the duration in seconds.
     * - Returns: the formatted string.
     */
    public func format(duration: TimeInterval?) -> String {
        var value = duration ?? 0
        if !value.isFinite {
            value = 0
        }
        if timeFormat == ZmanimFormatter.XSD_DURATION_FORMAT {
            return formatXSDDurationTime(duration: value)
        }
        var sb = ""
        if value < 0 {
            sb += "-"
        }
        let totalMillis = ZmanimFormatter.toMillis(abs(value))
        let hours = totalMillis / 3_600_000
        let minutes = totalMillis / 60_000 % 60
        let seconds = totalMillis / 1000 % 60
        let milliseconds = totalMillis % 1000
        sb += prependZeroHours ? String(format: "%02lld", hours) : String(hours)
        sb += ":"
        sb += String(format: "%02lld", minutes)
        if useSeconds {
            sb += ":"
            sb += String(format: "%02lld", seconds)
        }
        if useMillis {
            sb += "."
            sb += String(format: "%03lld", milliseconds)
        }
        return sb
    }

    /**
     * Formats a duration given in milliseconds. This is the same as `format(duration:)` with the value in seconds.
     */
    public func format(milliseconds: Double) -> String {
        return format(duration: milliseconds / 1000)
    }

    /** The whole number of milliseconds in a non-negative duration, like `Duration.toMillis()` (which truncates). */
    private static func toMillis(_ seconds: TimeInterval) -> Int64 {
        // round to the nearest microsecond first so that a value such as 0.0029999999 (3 ms in binary) is not truncated to 2
        let micros = (seconds * 1_000_000).rounded()
        return JavaMath.toLong(micros / 1000)
    }

    /**
     * Formats a date using this formatter's `DateFormatter` pattern (by default "h:mm:ss") in this formatter's time zone.
     *
     * - Parameter date: the date to format.
     * - Returns: the formatted string.
     */
    public func formatDate(date: Date) -> String {
        return formatDate(date: date, timeZone: timeZone)
    }

    /**
     * Formats a date using this formatter's `DateFormatter` pattern in the given time zone, like KosherJava's
     * `formatInstant(Instant, ZoneId)`.
     *
     * - Parameters:
     *   - date: the date to format.
     *   - timeZone: the time zone to format the date in.
     * - Returns: the formatted string.
     */
    public func formatDate(date: Date, timeZone: TimeZone) -> String {
        return ZmanimFormatter.makeDateFormatter(dateTimeFormat, timeZone).string(from: date)
    }

    /**
     * Formats a date as an <a href="https://www.w3.org/TR/xmlschema-2/#dateTime">xsd:dateTime</a> in this formatter's time
     * zone, such as 2026-03-08T07:02:41-04:00 (or Z for UTC).
     */
    public func formatXSDateTime(date: Date) -> String {
        return ZmanimFormatter.makeDateFormatter(ZmanimFormatter.XSD_DATE_TIME_PATTERN, timeZone).string(from: date)
    }

    /**
     * Formats a duration as an <a href="https://www.w3.org/TR/xmlschema-2/#duration">xsd:duration</a>, such as PT1H6M7.869S,
     * like Java's `Duration.toString()`. A negative duration has a single "-" in front (-PT1H30M), since the fields of an
     * xsd:duration can't be negative. A nil, NaN or infinite duration returns an empty string.
     *
     * - Parameter duration: the duration in seconds.
     * - Returns: the xsd:duration formatted string.
     */
    public func formatXSDDurationTime(duration: TimeInterval?) -> String {
        guard let duration = duration, duration.isFinite, abs(duration) < 9.2e12 else {
            return ""
        }
        // the duration in whole nanoseconds, from rounding to the nearest microsecond (finer than a Double holds here)
        let totalNanos = JavaMath.toLong((abs(duration) * 1_000_000).rounded()) * 1000
        var wholeSeconds = totalNanos / 1_000_000_000
        let nanos = totalNanos % 1_000_000_000
        if wholeSeconds == 0 && nanos == 0 {
            return "PT0S"
        }
        let hours = wholeSeconds / 3600
        let minutes = (wholeSeconds % 3600) / 60
        wholeSeconds = wholeSeconds % 60
        var result = duration < 0 ? "-PT" : "PT"
        if hours != 0 {
            result += "\(hours)H"
        }
        if minutes != 0 {
            result += "\(minutes)M"
        }
        if wholeSeconds == 0 && nanos == 0 {
            return result
        }
        result += "\(wholeSeconds)"
        if nanos > 0 {
            var fraction = String(format: "%09lld", nanos)
            while fraction.hasSuffix("0") {
                fraction.removeLast()
            }
            result += "." + fraction
        }
        return result + "S"
    }

    /** The xsd:dateTime pattern (Java's "yyyy-MM-dd'T'HH:mm:ssXXX"). */
    private static let XSD_DATE_TIME_PATTERN = "yyyy-MM-dd'T'HH:mm:ssXXXXX"

    private static func makeDateFormatter(_ pattern: String, _ timeZone: TimeZone) -> DateFormatter {
        let formatter = DateFormatter()
        formatter.locale = Locale(identifier: "en_US_POSIX")
        formatter.calendar = Calendar(identifier: .gregorian)
        formatter.timeZone = timeZone
        formatter.dateFormat = pattern
        return formatter
    }

    // MARK: - XML and JSON

    /// A value returned by one of a calendar's no-argument getters, used by `toXML(astronomicalCalendar:)` and
    /// `toJSON(astronomicalCalendar:)`.
    public enum Value {
        /// A zman, or nil when it can't be calculated.
        case date(Date?)
        /// A duration in seconds (such as a sha'ah zmanis), or nil when it can't be calculated.
        case duration(TimeInterval?)
    }

    /// The root element (XML) or key (JSON) for a calendar's zmanim.
    private static func rootName(_ astronomicalCalendar: AstronomicalCalendar) -> String? {
        if type(of: astronomicalCalendar) == AstronomicalCalendar.self {
            return "AstronomicalTimes"
        } else if type(of: astronomicalCalendar) == ComprehensiveZmanimCalendar.self {
            return "Zmanim"
        } else if type(of: astronomicalCalendar) == ZmanimCalendar.self {
            return "BasicZmanim"
        }
        return nil
    }

    /// The calendar's no-argument getter values split into zmanim (sorted by time), durations (sorted) and N/A values.
    private static func collect(_ astronomicalCalendar: AstronomicalCalendar)
        -> (dates: [(String, Date)], durations: [(String, TimeInterval)], other: [String]) {
        var dates: [(String, Date)] = []
        var durations: [(String, TimeInterval)] = []
        var other: [String] = []
        for (name, value) in astronomicalCalendar.getFormattableValues() {
            let tagName = String(name.dropFirst(3)) // remove "get"
            switch value {
            case .date(let date?):
                dates.append((tagName, date))
            case .duration(let duration?):
                durations.append((tagName, duration))
            default:
                other.append(tagName)
            }
        }
        // stable sorts, like Java's List.sort
        dates = dates.enumerated().sorted { ($0.element.1, $0.offset) < ($1.element.1, $1.offset) }.map { $0.element }
        durations = durations.enumerated().sorted { ($0.element.1, $0.offset) < ($1.element.1, $1.offset) }.map { $0.element }
        return (dates, durations, other)
    }

    /// The metadata shared by XML and JSON output.
    private static func metadata(_ astronomicalCalendar: AstronomicalCalendar)
        -> (date: String, type: String, offsetHours: Double, timeZoneName: String) {
        let timeZone = astronomicalCalendar.getGeoLocation().getTimeZone()
        let lastMidnight = astronomicalCalendar.getLocalDate().atStartOfDay(timeZone: timeZone)
        let offsetHours = Double(timeZone.secondsFromGMT(for: lastMidnight)) / 3600.0
        let style: TimeZone.NameStyle = timeZone.isDaylightSavingTime(for: lastMidnight) ? .daylightSaving : .standard
        let timeZoneName = timeZone.localizedName(for: style, locale: Locale.current) ?? timeZone.identifier
        return (astronomicalCalendar.getLocalDate().description, String(reflecting: type(of: astronomicalCalendar)),
                offsetHours, timeZoneName)
    }

    /**
     * A method that returns an XML formatted `String` representing the serialized calendar. The format used is:
     *
     * ```
     * <AstronomicalTimes date="1969-02-08" type="KosherSwift.AstronomicalCalendar" algorithm="US Naval Almanac Algorithm"
     *     location="Montreal, Quebec" latitude="45.497" longitude="-73.63" elevation="85.0"
     *     timeZoneName="Eastern Standard Time" timeZoneID="America/New_York" timeZoneOffset="-5.0">
     *   <SeaLevelSunset>1969-02-08T17:11:26-05:00</SeaLevelSunset>
     *   <TemporalHour>PT50M23.259S</TemporalHour>
     *   ...
     * </AstronomicalTimes>
     * ```
     *
     * Zmanim are sorted by time, then durations, then values that are not available ("N/A"). Text values are XML escaped.
     *
     * - Parameter astronomicalCalendar: the calendar to serialize.
     * - Returns: the XML formatted string.
     */
    public static func toXML(astronomicalCalendar: AstronomicalCalendar) -> String {
        let geoLocation = astronomicalCalendar.getGeoLocation()
        let formatter = ZmanimFormatter(timeFormat: XSD_DURATION_FORMAT, dateTimeFormat: "yyyy-MM-dd'T'HH:mm:ss",
                                        timeZone: geoLocation.getTimeZone())
        let meta = metadata(astronomicalCalendar)
        let root = rootName(astronomicalCalendar)
        var sb = "<" + (root ?? "")
        sb += " date=\"" + meta.date + "\""
        sb += " type=\"" + escapeXML(meta.type) + "\""
        sb += " algorithm=\"" + escapeXML(astronomicalCalendar.getAstronomicalCalculator().getCalculatorName()) + "\""
        sb += " location=\"" + escapeXML(geoLocation.getLocationName()) + "\""
        sb += " latitude=\"\(geoLocation.getLatitude())\""
        sb += " longitude=\"\(geoLocation.getLongitude())\""
        sb += " elevation=\"\(geoLocation.getElevation())\""
        sb += " timeZoneName=\"" + escapeXML(meta.timeZoneName) + "\""
        sb += " timeZoneID=\"" + escapeXML(geoLocation.getTimeZone().identifier) + "\""
        sb += " timeZoneOffset=\"\(meta.offsetHours)\""
        sb += ">\n"

        let values = collect(astronomicalCalendar)
        for (label, date) in values.dates {
            sb += "\t<" + label + ">" + formatter.formatXSDateTime(date: date) + "</" + label + ">\n"
        }
        for (label, duration) in values.durations {
            sb += "\t<" + label + ">" + formatter.format(duration: duration) + "</" + label + ">\n"
        }
        for label in values.other {
            sb += "\t<" + label + ">N/A</" + label + ">\n"
        }
        if let root = root {
            sb += "</" + root + ">"
        }
        return sb
    }

    /**
     * A method that returns a JSON formatted `String` representing the serialized calendar. The format used is:
     *
     * ```
     * {
     * "metadata":{
     *   "date":"1969-02-08",
     *   "type":"KosherSwift.AstronomicalCalendar",
     *   "algorithm":"US Naval Almanac Algorithm",
     *   "location":"Montreal, Quebec",
     *   "latitude":"45.497",
     *   "longitude":"-73.63",
     *   "elevation":"85.0",
     *   "timeZoneName":"Eastern Standard Time",
     *   "timeZoneID":"America/New_York",
     *   "timeZoneOffset":"-5.0"},
     * "AstronomicalTimes":{
     *   "Sunrise":"1969-02-08T07:30:16-05:00",
     *   "TemporalHour":"PT50M23.259S"
     *   ...
     * }
     * }
     * ```
     *
     * Text values are JSON escaped.
     *
     * - Parameter astronomicalCalendar: the calendar to serialize.
     * - Returns: the JSON formatted string.
     */
    public static func toJSON(astronomicalCalendar: AstronomicalCalendar) -> String {
        let geoLocation = astronomicalCalendar.getGeoLocation()
        let formatter = ZmanimFormatter(timeFormat: XSD_DURATION_FORMAT, dateTimeFormat: "yyyy-MM-dd'T'HH:mm:ss",
                                        timeZone: geoLocation.getTimeZone())
        let meta = metadata(astronomicalCalendar)
        var sb = "{\n\"metadata\":{\n"
        sb += "\t\"date\":\"" + meta.date + "\",\n"
        sb += "\t\"type\":\"" + escapeJSON(meta.type) + "\",\n"
        sb += "\t\"algorithm\":\"" + escapeJSON(astronomicalCalendar.getAstronomicalCalculator().getCalculatorName()) + "\",\n"
        sb += "\t\"location\":\"" + escapeJSON(geoLocation.getLocationName()) + "\",\n"
        sb += "\t\"latitude\":\"\(geoLocation.getLatitude())\",\n"
        sb += "\t\"longitude\":\"\(geoLocation.getLongitude())\",\n"
        sb += "\t\"elevation\":\"\(geoLocation.getElevation())\",\n"
        sb += "\t\"timeZoneName\":\"" + escapeJSON(meta.timeZoneName) + "\",\n"
        sb += "\t\"timeZoneID\":\"" + escapeJSON(geoLocation.getTimeZone().identifier) + "\",\n"
        sb += "\t\"timeZoneOffset\":\"\(meta.offsetHours)\""
        sb += "},\n\""
        sb += rootName(astronomicalCalendar) ?? ""
        sb += "\":{\n"

        let values = collect(astronomicalCalendar)
        for (label, date) in values.dates {
            sb += "\t\"" + label + "\":\"" + formatter.formatXSDateTime(date: date) + "\",\n"
        }
        for (label, duration) in values.durations {
            sb += "\t\"" + label + "\":\"" + formatter.format(duration: duration) + "\",\n"
        }
        for label in values.other {
            sb += "\t\"" + label + "\":\"N/A\",\n"
        }
        sb.removeLast(2) // the last ",\n"
        sb += "}\n}"
        return sb
    }

    // MARK: - Escaping

    /// Escapes the XML special characters `&`, `<`, `>`, `"` and `'` so a value can be placed in an element or attribute.
    public static func escapeXML(_ value: String) -> String {
        var result = ""
        for scalar in value.unicodeScalars {
            switch scalar {
            case "&": result += "&amp;"
            case "<": result += "&lt;"
            case ">": result += "&gt;"
            case "\"": result += "&quot;"
            case "'": result += "&apos;"
            default: result.unicodeScalars.append(scalar)
            }
        }
        return result
    }

    /// Escapes a value for use inside a JSON string: quotes, backslashes and control characters.
    public static func escapeJSON(_ value: String) -> String {
        var result = ""
        for scalar in value.unicodeScalars {
            switch scalar {
            case "\"": result += "\\\""
            case "\\": result += "\\\\"
            case "\n": result += "\\n"
            case "\r": result += "\\r"
            case "\t": result += "\\t"
            case "\u{08}": result += "\\b"
            case "\u{0C}": result += "\\f"
            default:
                if scalar.value < 0x20 {
                    result += String(format: "\\u%04x", scalar.value)
                } else {
                    result.unicodeScalars.append(scalar)
                }
            }
        }
        return result
    }
}
